    public void GenerateSlug_MixedCaseWithSpaces_StartsCorrectly()
    {
        var result = _formatter.GenerateSlug("My Blog Post Title");

        StringAssert.StartsWith(result, "my-");
    }

    [TestMethod]
    public void GenerateSlug_WhitespaceInput_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.GenerateSlug("   "));
    }

    // ── FormatCurrency ──────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(9.99m);

        StringAssert.StartsWith(result, "$");
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_EndsWith2Decimals()
    {
        var result = _formatter.FormatCurrency(10m);

        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(19.95m, "€");

        StringAssert.StartsWith(result, "€");
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_ContainsAmount()
    {
        var result = _formatter.FormatCurrency(19.95m, "€");

        StringAssert.Contains(result, "19.95");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_ContainsMinus()
    {
        var result = _formatter.FormatCurrency(-5.50m);

        StringAssert.Contains(result, "-");
    }

    [TestMethod]
    public void FormatCurrency_WholeNumber_ReturnsExpectedFormat()
    {
        var result = _formatter.FormatCurrency(100m);

        Assert.AreEqual("$100.00", result);
    }
}

